}

/** Notify `afterCommit` with frozen events, isolating a throw. */
export function notifyCommitted(
  hooks: CanaHooks | undefined,
  events: readonly CanaChangeEvent[]
): void {
  if (!hooks?.afterCommit || events.length === 0) return;
  try {
    hooks.afterCommit(Object.freeze(events.map((event) => Object.freeze({ ...event }))));
  } catch {
    // The write is durable. Propagating would report a failure for something
    // that succeeded, which is the false-negative half of a false green.
  }
}

/** Notify `afterRollback`, isolating a throw. */
export function notifyRolledBack(
  hooks: CanaHooks | undefined,
  outcome: 'rolled-back' | 'unknown',
  reason?: string
): void {
  if (!hooks?.afterRollback) return;
  try {
    hooks.afterRollback(outcome, reason);
  } catch {
    // The transaction already failed; a failing hook must not mask why.
  }
}
/**
 * Table operations: CRUD and bulk (JUM-405).
 *
 * Everything here runs inside a transaction supplied by the caller, and every
 * write records a change event into that transaction's buffer rather than
 * emitting one. The buffer is released only if the transaction commits — see
 * `transaction.ts` for why announcing a write before it is durable is worse
 * than announcing it late.
 *
 * Two decisions in this file are worth stating, because both are places where
 * the convenient behaviour is the wrong one:
 *
 * 1. **`update` is read-modify-write inside the same transaction.** Reading in
 *    one transaction and writing in another is a lost update the moment two
 *    tabs touch the same record, and offline-first apps have two tabs open
 *    constantly. Because the read is an IndexedDB request, awaiting it does not
 *    close the auto-commit window.
 *
 * 2. **`update` on a missing key fails rather than inserting.** An upsert
 *    disguised as an update turns a stale key — a record another tab deleted —
 *    into a resurrected row that no longer has the fields the rest of the schema
 *    expects. `put` is available for callers who genuinely mean upsert.
 */

import type {
  CanaBulkWriteResult,
  CanaChangeType,
  CanaKey,
  CanaQuery,
  CanaQueryPlan,
  CanaTable,
  CanaWriteResult
} from '../contracts';
import { canaError, requestToPromise, translateError } from './errors';
import { planQuery, runCount, runQuery } from './query';
import type { CanaHooks } from './hooks';
import { applyBeforeWrite } from './hooks';
import type { ChangeBuffer } from './transaction';

export interface TableContext {
  readonly transaction: IDBTransaction;
  readonly buffer: ChangeBuffer;
  readonly correlationId: string;
  readonly hooks?: CanaHooks;
}

/** Whether the store carries its key inside the record. */
function isInbound(store: IDBObjectStore): boolean {
  return store.keyPath !== null;
}

function assertKeyUsage(store: IDBObjectStore, key: CanaKey | undefined, operation: string): void {
  if (key !== undefined && isInbound(store)) {
    // IndexedDB reports this as a bare DataError, which does not say that the
    // store's own keyPath is the reason the explicit key is unacceptable.
    throw canaError(
      'InvalidRequest',
      `${operation} on "${store.name}" was given an explicit key, but the store has an inbound `
        + `keyPath (${String(store.keyPath)}). The key must live inside the record.`,
      { store: store.name, key }
    );
  }
  if (key === undefined && !isInbound(store) && !store.autoIncrement) {
    throw canaError(
      'InvalidRequest',
      `${operation} on "${store.name}" needs an explicit key: the store uses outbound keys and `
        + 'does not generate them.',
      { store: store.name }
    );
  }
}

/** Read an inbound key out of a record, following a simple or compound keyPath. */
function extractKey(store: IDBObjectStore, record: unknown): CanaKey | undefined {
  const path = store.keyPath;
  if (path === null) return undefined;

  const read = (segments: string): unknown => segments
    .split('.')
    .reduce<unknown>(
      (value, segment) => (value === null || typeof value !== 'object'
        ? undefined
        : (value as Record<string, unknown>)[segment]),
      record
    );

  if (Array.isArray(path)) {
    const parts = path.map((segment) => read(segment));
    return parts.some((part) => part === undefined) ? undefined : (parts as CanaKey);
  }
  return read(path) as CanaKey | undefined;
}

/**
 * A table bound to one transaction.
 *
 * A closure rather than a class: the transaction, buffer and correlation id are
 * fixed for the table's whole lifetime, so there is no mutable state and no
 * method that can be called on a half-configured instance.
 */
export function createTable<TRecord, TKey extends CanaKey = CanaKey>(
  name: string,
  context: TableContext
): CanaTable<TRecord, TKey> {
  const store = (): IDBObjectStore => {
    try {
      return context.transaction.objectStore(name);
    } catch (error) {
      // Reached when the store was not in the transaction's scope, or when the
      // transaction has already finished — the auto-commit case, which is the
      // single most common misuse and deserves to say so.
      throw translateError(error, { store: name });
    }
  };

  const record = (type: CanaChangeType, key: CanaKey | undefined, value?: unknown): void => {
    context.buffer.record({
      type,
      store: name,
      correlationId: context.correlationId,
      ...(key === undefined ? {} : { key }),
      ...(value === undefined ? {} : { record: value })
    } as Parameters<ChangeBuffer['record']>[0]);
  };

  /**
   * Run `beforeWrite` and return what should actually be written.
   *
   * Called before the IndexedDB request is issued, so a veto costs nothing and a
   * transform is what lands on disk rather than something reconciled afterwards.
   */
  const throughHooks = (
    type: CanaChangeType,
    key: CanaKey | undefined,
    value: unknown
  ): unknown => applyBeforeWrite(
    context.hooks,
    {
      store: name,
      type,
      correlationId: context.correlationId,
      ...(key === undefined ? {} : { key }),
      ...(value === undefined ? {} : { record: value })
    },
    value
  );

  // Generic over the request's result type because `IDBRequest<T>` is invariant:
  // `add`/`put` resolve to a key and `delete` resolves to undefined, and no
  // single non-generic signature accepts both.
  const bulk = async <TWritten extends IDBValidKey | undefined>(
    items: readonly unknown[],
    apply: (target: IDBObjectStore, item: unknown) => IDBRequest<TWritten>,
    type: CanaChangeType,
    /**
     * True for `bulkPut`, where each row may be either a create or an update.
     *
     * Without this a bulk put labelled every row `updated`, including brand-new
     * records — so a subscriber driving an incremental UI would never learn a
     * row had appeared, and `beforeWrite` hooks saw the wrong type. The single
     * `put` had always probed; the bulk path silently did not.
     */
    classifyPerItem = false
  ): Promise<CanaBulkWriteResult> => {
    const target = store();
    const keys: CanaKey[] = [];
    const failedAt: number[] = [];

    for (let index = 0; index < items.length; index += 1) {
      const source = items[index];

      // Probed before the write, since afterwards every row exists.
      let itemType = type;
      const probeKey = classifyPerItem && isInbound(target)
        ? extractKey(target, source)
        : undefined;
      if (probeKey !== undefined) {
        // Sequential for the same reason the write below is: the probe belongs
        // to this row and must not race ahead of it.
        // eslint-disable-next-line no-await-in-loop
        const existing = await requestToPromise(
          target.count(probeKey as IDBValidKey),
          { store: name }
        );
        itemType = existing > 0 ? 'updated' : 'created';
      } else if (classifyPerItem) {
        // Outbound or generated key: nothing to probe with, so the row can only
        // be treated as new.
        itemType = 'created';
      }

      // A delete carries no record, so there is nothing for a hook to transform.
      const item = itemType === 'deleted'
        ? source
        : throughHooks(itemType, undefined, source);
      // Sequential on purpose. Issuing every request up front and awaiting them
      // together reorders the writes relative to the input, and `failedAt`
      // indices would then point at the wrong rows — which is precisely the
      // information a caller reconciling a partial import needs to be correct.
      // eslint-disable-next-line no-await-in-loop
      const written = await requestToPromise(apply(target, item), { store: name })
        .catch((error: unknown) => {
          failedAt.push(index);
          throw error;
        });
      // `delete` resolves to undefined, so the key is the input itself; for
      // add/put it is what the store assigned, which may be generated.
      const key = (written ?? item) as CanaKey;
      keys.push(key);
      record(itemType, key, itemType === 'deleted' ? undefined : item);
    }

    return {
      outcome: 'committed',
      keys,
      ...(failedAt.length === 0 ? {} : { failedAt }),
      events: []
    };
  };

  return {
    name,

    get(key: TKey): Promise<TRecord | undefined> {
      return requestToPromise<TRecord | undefined>(
        store().get(key as IDBValidKey) as IDBRequest<TRecord | undefined>,
        { store: name, key }
      );
    },

    async add(value: TRecord, key?: TKey): Promise<CanaWriteResult> {
      const target = store();
      assertKeyUsage(target, key, 'add');

      const writing = throughHooks('created', key, value) as TRecord;
      const written = await requestToPromise(
        key === undefined ? target.add(writing) : target.add(writing, key as IDBValidKey),
        { store: name, key }
      );

      record('created', written as CanaKey, writing);
      return { outcome: 'committed', key: written as CanaKey, events: [] };
    },

    async put(value: TRecord, key?: TKey): Promise<CanaWriteResult> {
      const target = store();
      assertKeyUsage(target, key, 'put');

      // Whether this is a create or an update is only knowable by looking first,
      // and subscribers depend on the distinction. The read is an IDB request in
      // the same transaction, so it costs a request, not the transaction.
      const probeKey = key ?? (isInbound(target) ? extractKey(target, value) : undefined);
      const existed = probeKey === undefined
        ? false
        : (await requestToPromise(target.count(probeKey as IDBValidKey), { store: name })) > 0;

      const writing = throughHooks(existed ? 'updated' : 'created', key, value) as TRecord;
      const written = await requestToPromise(
        key === undefined ? target.put(writing) : target.put(writing, key as IDBValidKey),
        { store: name, key }
      );

      record(existed ? 'updated' : 'created', written as CanaKey, writing);
      return { outcome: 'committed', key: written as CanaKey, events: [] };
    },

    async update(key: TKey, changes: Partial<TRecord>): Promise<CanaWriteResult> {
      const target = store();

      const current = await requestToPromise<TRecord | undefined>(
        target.get(key as IDBValidKey) as IDBRequest<TRecord | undefined>,
        { store: name, key }
      );

      if (current === undefined) {
        throw canaError(
          'NotFound',
          `Cannot update "${String(key)}" in "${name}": no such record. `
            + 'update does not insert — use put when an upsert is intended.',
          { store: name, key }
        );
      }

      const merged = throughHooks('updated', key, { ...current, ...changes }) as TRecord;
      const written = await requestToPromise(
        isInbound(target) ? target.put(merged) : target.put(merged, key as IDBValidKey),
        { store: name, key }
      );

      record('updated', written as CanaKey, merged);
      return { outcome: 'committed', key: written as CanaKey, events: [] };
    },

    async delete(key: TKey): Promise<CanaWriteResult> {
      const target = store();

      // Deleting a key that is not there succeeds silently in IndexedDB.
      // Checking first is what keeps a change event from claiming a deletion
      // that removed nothing, which a subscriber would otherwise act on.
      const present = await requestToPromise(target.count(key as IDBValidKey), { store: name });

      await requestToPromise(target.delete(key as IDBValidKey), { store: name, key });

      if (present > 0) record('deleted', key);
      return { outcome: 'committed', key, events: [] };
    },

    async clear(): Promise<CanaWriteResult> {
      await requestToPromise(store().clear(), { store: name });
      record('cleared', undefined);
      return { outcome: 'committed', events: [] };
    },

    bulkAdd(records: readonly TRecord[]): Promise<CanaBulkWriteResult> {
      return bulk(records, (target, item) => target.add(item), 'created');
    },

    bulkPut(records: readonly TRecord[]): Promise<CanaBulkWriteResult> {
      // `classifyPerItem` so each row reports created or updated as it actually
      // is, matching what the single `put` has always done.
      return bulk(records, (target, item) => target.put(item), 'updated', true);
    },

    bulkDelete(keys: readonly TKey[]): Promise<CanaBulkWriteResult> {
      return bulk(
        keys,
        (target, item) => target.delete(item as IDBValidKey) as IDBRequest<undefined>,
        'deleted'
      );
    },

    count(query?: CanaQuery): Promise<number> {
      return runCount(store(), query);
    },

    query(query?: CanaQuery): Promise<readonly TRecord[]> {
      return runQuery<TRecord>(store(), query);
    },

    async explain(
      query?: CanaQuery
    ): Promise<{ records: readonly TRecord[]; plan: CanaQueryPlan }> {
      const plan = planQuery(name, query);
      const records = await runQuery<TRecord>(store(), query);
      return { records, plan };
    }
  };
}
/**
 * Cana public contracts (JUM-400).
 *
 * The property this file exists to enforce: **no IndexedDB type crosses this
 * boundary.** Not `IDBDatabase`, not `IDBTransaction`, not `IDBValidKey`, not a
 * `DOMException`. A consumer that can name an IndexedDB type can also depend on
 * one, and then swapping the driver stops being a configuration change — which is
 * the entire point of the hexagonal boundary (Reqs 015/016).
 *
 * Two consequences shape everything below:
 *
 * 1. **Keys are our own type, not `IDBValidKey`.** IndexedDB accepts a specific
 *    set of key types with its own comparison rules; we restate that set so the
 *    contract is readable without the spec open, and so a future non-IndexedDB
 *    backend is not forced to satisfy a DOM interface.
 *
 * 2. **Errors are plain data with a discriminant, never `Error` subclasses.**
 *    Cana runs its engine in a worker, and `postMessage` uses structured clone,
 *    which **strips prototypes**. An `instanceof CanaQuotaError` check that works
 *    in tests silently becomes `false` in production the moment the engine moves
 *    off the main thread. So the taxonomy is a tagged union carried as data, and
 *    `isCanaError`/`isQuotaExceeded` are the supported way to branch on it.
 */

/* ------------------------------------------------------------------ *
 * Keys
 * ------------------------------------------------------------------ */

/**
 * A value usable as a primary key or index key.
 *
 * Mirrors the IndexedDB valid-key set deliberately rather than importing
 * `IDBValidKey`: the contract must be legible on its own, and a backend that is
 * not IndexedDB must be able to satisfy it.
 */
// CanaKey and CanaKeyArray are mutually recursive by definition: an array of keys
// is itself a key. No declaration order satisfies no-use-before-define, so it is
// disabled at this one site rather than by relaxing the rule repo-wide.
// eslint-disable-next-line no-use-before-define
export interface CanaKeyArray extends Array<CanaKey> {}

export type CanaKey = number | string | Date | ArrayBufferView | ArrayBuffer | CanaKeyArray;

/** A compound key path, e.g. `['tenantId', 'email']`. */
export type CanaKeyPath = string | readonly string[];

/* ------------------------------------------------------------------ *
 * Errors — data, not classes
 * ------------------------------------------------------------------ */

/**
 * Every failure Cana can report.
 *
 * Kept flat and exhaustive so a `switch` over it is checkable, and so a consumer
 * can handle the cases that matter to a user (`QuotaExceeded`, `Evicted`,
 * `Unavailable`) without pattern-matching on message strings.
 */
export type CanaErrorCode =
  /**
   * No usable IndexedDB: private browsing, or an unsupported browser.
   * Terminal, not degraded — there is no fallback to fall back to.
   */
  | 'Unavailable'
  /** The origin's storage budget is exhausted. The write did not happen. */
  | 'QuotaExceeded'
  /**
   * A database that previously existed is gone or at an unexpected version.
   *
   * This is the single most important code in the taxonomy. An evicted database
   * and a brand-new one are indistinguishable by inspection — both open empty —
   * and reporting the first as the second presents lost work as a welcome screen.
   */
  | 'Evicted'
  /** A schema upgrade did not complete; the database may be at an indeterminate version. */
  | 'UpgradeFailed'
  /** Another connection is blocking a version change, or the upgrade timed out waiting. */
  | 'UpgradeBlocked'
  /** A uniqueness constraint rejected the write. */
  | 'ConstraintViolation'
  /** The requested key or record does not exist. */
  | 'NotFound'
  /** The transaction was aborted, by the caller or by the engine. */
  | 'TransactionAborted'
  /**
   * The transaction's auto-commit window closed before the operation ran.
   *
   * Distinct from `TransactionAborted` on purpose: this one is almost always a
   * caller mistake (awaiting something outside the transaction), and conflating
   * the two sends people looking in the wrong place.
   */
  | 'TransactionInactive'
  /** The operation was cancelled by the caller. */
  | 'Cancelled'
  /** A bounded queue rejected the request rather than growing without limit. */
  | 'Backpressure'
  /**
   * The worker died or the connection dropped and the outcome cannot be
   * determined. Not a failure and not a success — see `CanaWriteOutcome`.
   */
  | 'UnknownOutcome'
  /** The engine rejected the request as malformed before touching storage. */
  | 'InvalidRequest'
  /** Anything the engine could not classify. Carries `cause` for diagnosis. */
  | 'Internal';

/**
 * A Cana failure, as plain data.
 *
 * `readonly` throughout and prototype-free by construction, so it survives
 * `structuredClone` across the worker boundary unchanged.
 */
export interface CanaError {
  readonly canaError: true;
  readonly code: CanaErrorCode;
  readonly message: string;
  /** Store involved, when the failure is store-scoped. */
  readonly store?: string;
  /** Key involved, when the failure is key-scoped. */
  readonly key?: CanaKey;
  /**
   * Whether retrying the identical operation could plausibly succeed.
   *
   * Recorded by the engine rather than inferred by the caller: only the engine
   * knows whether a failure was transient contention or a permanent constraint.
   */
  readonly retryable: boolean;
  /**
   * Original error text, flattened to a string.
   *
   * A string rather than the error object because structured clone would strip a
   * `DOMException` down to something unrecognisable anyway; flattening here keeps
   * the diagnosis and drops the false promise of a live object.
   */
  readonly cause?: string;
}

/** Narrow an unknown rejection to a Cana failure. */
export function isCanaError(value: unknown): value is CanaError {
  return typeof value === 'object'
    && value !== null
    && (value as { canaError?: unknown }).canaError === true;
}

/** Narrow to a specific code. Preferred over comparing `message` strings. */
export function isCanaErrorCode<TCode extends CanaErrorCode>(
  value: unknown,
  code: TCode
): value is CanaError & { code: TCode } {
  return isCanaError(value) && value.code === code;
}

/* ------------------------------------------------------------------ *
 * Write outcomes — three states, not two
 * ------------------------------------------------------------------ */

/**
 * The result of a mutation.
 *
 * Three states rather than two, and the third is the reason this type exists: if
 * a worker dies mid-transaction, the client holds a promise that will never
 * settle. Resolving it as failure risks a duplicate write on retry; resolving it
 * as success risks reporting data that was never committed. `unknown` forces the
 * caller to reconcile instead of guessing (JUM-411).
 */
export type CanaWriteOutcome = 'committed' | 'rolled-back' | 'unknown';

/* ------------------------------------------------------------------ *
 * Change events
 * ------------------------------------------------------------------ */

export type CanaChangeType = 'created' | 'updated' | 'deleted' | 'cleared';

/**
 * A committed change, as published to the Message Mediator (JUM-412).
 *
 * Published **only** for committed writes. A rolled-back transaction that emitted
 * events would leave every listener holding state the database does not have.
 */
export interface CanaChangeEvent<TRecord = unknown> {
  readonly type: CanaChangeType;
  readonly store: string;
  readonly key?: CanaKey;
  /** Absent for `deleted` and `cleared`. */
  readonly record?: TRecord;
  /**
   * Monotonic per-database sequence number.
   *
   * The ordering guarantee listeners rely on, and what makes resubscription
   * possible: a client that was closed resumes from its last cursor rather than
   * replaying everything or silently missing the gap (JUM-413).
   */
  readonly cursor: number;
  /** Correlates the event with the originating request across tabs and workers. */
  readonly correlationId: string;
  /** Epoch milliseconds, engine clock. */
  readonly at: number;
  /**
   * Identifies the writer, so a tab can recognise its own echo.
   *
   * Without it, applying every event unconditionally makes a tab re-apply the
   * change it just made, which is how cursor jitter and lost focus happen.
   */
  readonly originId: string;
}

/* ------------------------------------------------------------------ *
 * Storage state — quota, persistence, eviction (JUM-560)
 * ------------------------------------------------------------------ */

/**
 * What Cana knows about the durability of the copy it holds.
 *
 * Exposed rather than internal because, under the no-fallback requirement, an
 * application that cannot see this state cannot warn a user before their work is
 * gone.
 */
export interface CanaStorageState {
  /**
   * Whether the origin obtained persistent storage.
   *
   * `false` means the browser may reclaim the data under pressure. `unknown`
   * means the API is unavailable and durability cannot be claimed either way —
   * which is not the same as `false` and must not be flattened into it.
   */
  readonly persistent: boolean | 'unknown';
  /** Bytes in use, when the environment reports it. */
  readonly usageBytes?: number;
  /** Bytes available, when the environment reports it. */
  readonly quotaBytes?: number;
  /**
   * True once usage crosses the configured headroom threshold.
   *
   * Deliberately raised *before* hard failure so a consumer still has room to
   * offer an export — which, with no fallback, is the only recovery that exists.
   */
  readonly nearQuota: boolean;
  /**
   * Set when the engine detected that a previously-existing database is gone.
   *
   * The flag exists so `Evicted` is reportable as a *state* and not only as an
   * error on the next write.
   */
  readonly evicted: boolean;
}

/* ------------------------------------------------------------------ *
 * Schema
 * ------------------------------------------------------------------ */

export interface CanaIndexSchema {
  readonly name: string;
  readonly keyPath: CanaKeyPath;
  readonly unique?: boolean;
  /**
   * Index each element of an array-valued key path separately.
   *
   * Mutually exclusive with a compound `keyPath` in IndexedDB; the schema
   * validator rejects the combination rather than letting the browser throw a
   * `DOMException` from somewhere less obvious.
   */
  readonly multiEntry?: boolean;
}

export interface CanaStoreSchema {
  readonly name: string;
  /**
   * Inbound key: the key lives inside the record at this path.
   *
   * Mutually exclusive with `autoIncrement` without a keyPath (outbound keys).
   * Getting this wrong is the most common source of silent divergence between
   * IndexedDB implementations, so the validator is explicit about it (JUM-404).
   */
  readonly keyPath?: CanaKeyPath;
  readonly autoIncrement?: boolean;
  readonly indexes?: readonly CanaIndexSchema[];
}

export interface CanaSchema {
  /** Integer, monotonically increasing. Downgrades are rejected, not attempted. */
  readonly version: number;
  readonly stores: readonly CanaStoreSchema[];
}

/* ------------------------------------------------------------------ *
 * Queries
 * ------------------------------------------------------------------ */

export interface CanaRange {
  readonly lower?: CanaKey;
  readonly upper?: CanaKey;
  readonly lowerOpen?: boolean;
  readonly upperOpen?: boolean;
}

export type CanaDirection = 'next' | 'prev' | 'nextunique' | 'prevunique';

/**
 * A query plan.
 *
 * `index` is the load-bearing field. A query that names no index and no key range
 * is a full scan, and the engine reports that in `CanaQueryPlan` so a caller can
 * tell an indexed lookup from a scan that merely happens to be fast on ten rows.
 */
export interface CanaQuery {
  readonly index?: string;
  readonly equals?: CanaKey;
  readonly range?: CanaRange;
  readonly direction?: CanaDirection;
  readonly offset?: number;
  readonly limit?: number;
  readonly distinct?: boolean;
}

/**
 * How the engine intends to satisfy a query.
 *
 * Exposed because the acceptance criterion for JUM-406 is that indexed queries
 * *use their index*: an implementation backed by in-memory array methods passes
 * every functional test and then fails at scale. This makes the distinction
 * assertable in a test rather than a matter of trust.
 */
export interface CanaQueryPlan {
  readonly store: string;
  readonly usedIndex?: string;
  readonly fullScan: boolean;
  readonly boundedByRange: boolean;
  /** Applied by the cursor, not after materialising the result set. */
  readonly appliedOffsetInCursor: boolean;
}

/* ------------------------------------------------------------------ *
 * Client surface
 * ------------------------------------------------------------------ */

export interface CanaWriteResult {
  readonly outcome: CanaWriteOutcome;
  readonly key?: CanaKey;
  /** Emitted only when `outcome === 'committed'`. */
  readonly events: readonly CanaChangeEvent[];
}

export interface CanaBulkWriteResult {
  readonly outcome: CanaWriteOutcome;
  readonly keys: readonly CanaKey[];
  /**
   * Indices within the input batch that failed, when the engine applied a
   * partial bulk.
   *
   * Present rather than collapsed into a single error because a caller
   * reconciling a 1000-row import needs to know *which* rows, and re-running the
   * whole batch is not always safe.
   */
  readonly failedAt?: readonly number[];
  readonly events: readonly CanaChangeEvent[];
}

export interface CanaTable<TRecord, TKey extends CanaKey = CanaKey> {
  readonly name: string;
  get(key: TKey): Promise<TRecord | undefined>;
  add(record: TRecord, key?: TKey): Promise<CanaWriteResult>;
  put(record: TRecord, key?: TKey): Promise<CanaWriteResult>;
  update(key: TKey, changes: Partial<TRecord>): Promise<CanaWriteResult>;
  delete(key: TKey): Promise<CanaWriteResult>;
  clear(): Promise<CanaWriteResult>;
  bulkAdd(records: readonly TRecord[]): Promise<CanaBulkWriteResult>;
  bulkPut(records: readonly TRecord[]): Promise<CanaBulkWriteResult>;
  bulkDelete(keys: readonly TKey[]): Promise<CanaBulkWriteResult>;
  count(query?: CanaQuery): Promise<number>;
  query(query?: CanaQuery): Promise<readonly TRecord[]>;
  /** Same as `query`, plus the plan the engine used. */
  explain(query?: CanaQuery): Promise<{ records: readonly TRecord[]; plan: CanaQueryPlan }>;
}

/**
 * Transaction scope.
 *
 * Deliberately does **not** expose commit or abort as separate awaits: the
 * IndexedDB auto-commit window closes as soon as the event loop yields with no
 * pending request, so a caller who awaits anything unrelated inside the scope
 * loses the transaction. The engine owns the boundary and reports
 * `TransactionInactive` when that happens, which is the honest failure rather
 * than a mysterious one (JUM-407).
 */
export interface CanaTransactionScope {
  table<TRecord, TKey extends CanaKey = CanaKey>(name: string): CanaTable<TRecord, TKey>;
  abort(reason?: string): void;
}

export type CanaTransactionMode = 'readonly' | 'readwrite';

/**
 * What a transaction reports back.
 *
 * `correlationId` and `attemptedAt` are present on **every** outcome, including
 * `unknown`. That is the point: `unknown` is the one result a caller must act
 * on, and acting on it means calling `resolveWrite(correlationId, attemptedAt)`.
 * An earlier shape omitted them, so the only outcome that needed reconciling was
 * the one that could not be reconciled.
 */
export interface CanaTransactionResult<TResult> {
  readonly outcome: CanaWriteOutcome;
  readonly result?: TResult;
  /** Empty unless `outcome === 'committed'`. */
  readonly events: readonly CanaChangeEvent[];
  /** Identifies this transaction in the operation ledger. */
  readonly correlationId: string;
  /** Epoch milliseconds the transaction was started. */
  readonly attemptedAt: number;
}

export interface CanaClient {
  readonly name: string;
  readonly version: number;

  open(): Promise<void>;
  close(): Promise<void>;

  table<TRecord, TKey extends CanaKey = CanaKey>(name: string): CanaTable<TRecord, TKey>;

  transaction<TResult>(
    mode: CanaTransactionMode,
    stores: readonly string[],
    body: (scope: CanaTransactionScope) => Promise<TResult> | TResult,
  ): Promise<CanaTransactionResult<TResult>>;

  /** Current durability state. See `CanaStorageState`. */
  storageState(): Promise<CanaStorageState>;

  /**
   * Subscribe to committed changes.
   *
   * `sinceCursor` is what makes recovery possible: a client that was closed
   * resumes from its last cursor instead of replaying from zero or silently
   * skipping the gap.
   */
  subscribe(
    listener: (event: CanaChangeEvent) => void,
    options?: { sinceCursor?: number },
  ): () => void;

  /**
   * Export the whole database as plain data.
   *
   * Part of the contract, not a utility, because under the no-fallback
   * requirement this is the only recovery path a user has. It must therefore work
   * against a degraded database — which is exactly when it is needed.
   */
  exportAll(): Promise<Record<string, readonly unknown[]>>;
}
/**
 * Durability policy (JUM-415).
 *
 * `storage.ts` answers mechanical questions — is it persistent, how full is it,
 * was it evicted. This file answers the product question: given those, what is
 * the application allowed to tell its user?
 *
 * It exists because the mechanical answers are easy to round off in the
 * dangerous direction. Three roundings are refused here:
 *
 * 1. **`persistent: 'unknown'` is not `durable`.** The Storage API is absent in
 *    some browsers and in some private modes. Treating absence as "probably
 *    fine" lets an application promise durability it has no evidence for, and
 *    the user finds out when their work is gone.
 *
 * 2. **Near-quota is not a failure, and not nothing.** It is the only warning
 *    that arrives *before* data loss. Collapsing it into "healthy" wastes the
 *    one chance to act; collapsing it into "failed" trains people to ignore it.
 *
 * 3. **Undetectable eviction is its own state.** When no tombstone can be
 *    written, the engine cannot tell a first run from a wipe — ever, for that
 *    origin. Reporting that as "not evicted" is a claim the engine cannot
 *    support (see JUM-560).
 *
 * The policy deliberately has no `recover()`. Under the no-fallback decision
 * there is no second store to fall back to, so the only honest recovery path is
 * the application's own export/import — `CanaClient.exportAll()`.
 */

import type { CanaStorageState } from '../contracts';
import type { EvictionVerdict } from './storage';

/**
 * How durable the data actually is, worst case first.
 *
 * Ordered so a caller can compare, and named for what is true rather than for
 * how alarming it is.
 */
export type DurabilityLevel =
  /** Data was there and is gone. */
  | 'lost'
  /** Storage is close enough to quota that the browser may evict. */
  | 'at-risk'
  /** Not persistent, or persistence cannot be confirmed: eviction is possible. */
  | 'best-effort'
  /** The browser granted persistent storage. */
  | 'durable';

export interface DurabilityAssessment {
  readonly level: DurabilityLevel;
  /** True when the engine cannot detect eviction at all for this origin. */
  readonly evictionDetectable: boolean;
  /** Plain-language reason, suitable for showing a user. */
  readonly summary: string;
  /**
   * What the application should do, or an empty list when nothing is warranted.
   *
   * Advice is separate from the level because the same level can call for
   * different action depending on whether detection works.
   */
  readonly advice: readonly string[];
}

export interface DurabilityPolicy {
  /**
   * Whether to ask for persistent storage when the client opens.
   *
   * Defaults to false. Asking prompts the user in some browsers, and a prompt
   * fired by a library at an arbitrary moment is a prompt that gets denied — a
   * denial the origin may then be stuck with.
   */
  readonly requestPersistenceOnOpen?: boolean;
  /** Fraction of quota at which usage counts as at-risk. */
  readonly nearQuotaRatio?: number;
}

export const DEFAULT_DURABILITY_POLICY: Required<DurabilityPolicy> = {
  requestPersistenceOnOpen: false,
  nearQuotaRatio: 0.85
};

function usageSummary(state: CanaStorageState): string {
  const { usageBytes, quotaBytes } = state;
  if (usageBytes === undefined || quotaBytes === undefined || quotaBytes === 0) {
    return 'Storage is close to its quota.';
  }
  const percent = Math.round((usageBytes / quotaBytes) * 100);
  return `Storage is ${percent}% of the available quota.`;
}

/**
 * Turn observed storage state into a durability verdict.
 *
 * Pure, so the policy is testable without a browser and without the timing that
 * makes storage behaviour hard to reproduce.
 */
export function assessDurability(
  state: CanaStorageState,
  verdict?: EvictionVerdict | null
): DurabilityAssessment {
  const evictionDetectable = verdict?.reason !== 'undetectable-no-tombstone';

  if (state.evicted || verdict?.evicted === true) {
    return {
      level: 'lost',
      evictionDetectable,
      summary: 'The browser deleted this database to reclaim space. Local data written before '
        + 'now is gone and cannot be recovered from the browser.',
      advice: [
        'Tell the user their local data was cleared by the browser, rather than showing an '
          + 'empty app that looks like a fresh install.',
        'Re-sync from the server if there is one; otherwise the loss is final.',
        'Request persistent storage before writing again.'
      ]
    };
  }

  if (state.nearQuota) {
    return {
      level: 'at-risk',
      evictionDetectable,
      summary: `${usageSummary(state)
      } At this level the browser may evict the database without warning.`,
      advice: [
        'Free space: remove cached or derived records that can be rebuilt.',
        'Export anything the user cannot afford to lose.',
        ...(state.persistent === true
          ? []
          : ['Request persistent storage — it is the only thing that makes eviction unlikely.'])
      ]
    };
  }

  if (state.persistent === true) {
    return {
      level: 'durable',
      evictionDetectable,
      summary: 'The browser granted persistent storage: this database will not be evicted '
        + 'automatically under storage pressure.',
      advice: evictionDetectable
        ? []
        : ['Eviction cannot be detected for this origin, so a wipe would look like a first run.']
    };
  }

  // Covers both `false` and `'unknown'`, and says which — because "the browser
  // refused" and "we cannot tell" call for different messages, even though
  // neither is a durability guarantee.
  const reason = state.persistent === false
    ? 'The browser did not grant persistent storage'
    : 'Persistent storage could not be confirmed in this browser';

  return {
    level: 'best-effort',
    evictionDetectable,
    summary: `${reason}, so this database can be evicted under storage pressure.`,
    advice: [
      ...(state.persistent === false
        ? ['Persistence was refused; treat local data as a cache, not as the record of truth.']
        : ['Do not report local data as durable — there is no evidence that it is.']),
      ...(evictionDetectable
        ? []
        : ['Eviction is undetectable for this origin: a wipe would be indistinguishable from a '
          + 'first run, so the app cannot tell the user what happened.'])
    ]
  };
}

/** True when the level means the application should stop treating writes as safe. */
export function requiresUserAttention(level: DurabilityLevel): boolean {
  return level === 'lost' || level === 'at-risk';
}
/**
 * Schema validation and application (JUM-404).
 *
 * Key handling is the least visible and most divergent part of IndexedDB, and it
 * is exactly where a from-scratch engine drifts without anyone noticing. The
 * validator here rejects, up front and with a readable message, the combinations
 * the browser would otherwise reject later from somewhere much less obvious.
 *
 * The three that actually bite:
 *
 * 1. **`multiEntry` with a compound `keyPath`.** IndexedDB forbids it. Left
 *    unchecked, the browser throws `InvalidAccessError` from inside a
 *    `versionchange` transaction, which surfaces as a failed upgrade rather than
 *    as "your schema is wrong".
 * 2. **`autoIncrement` with an outbound key, then supplying a key anyway.** Legal
 *    at schema level, contradictory at call level. Caught in the write path, but
 *    the schema records which shape a store uses so the check is possible at all.
 * 3. **An empty compound `keyPath`.** Accepted by some implementations, rejected
 *    by others. Rejected here so behaviour does not depend on the browser.
 */

import type {
  CanaIndexSchema, CanaKeyPath, CanaSchema, CanaStoreSchema
} from '../contracts';
import { canaError } from './errors';

/** How a store's primary key is supplied. */
export type KeyStrategy =
  /** Key lives inside the record, at `keyPath`. */
  | 'inbound'
  /** Key is supplied by the caller alongside the record. */
  | 'outbound'
  /** Key is generated by the store. */
  | 'generated-outbound'
  /** Key lives inside the record and is generated when absent. */
  | 'generated-inbound';

export function keyStrategyOf(store: CanaStoreSchema): KeyStrategy {
  if (store.keyPath !== undefined) {
    return store.autoIncrement ? 'generated-inbound' : 'inbound';
  }
  return store.autoIncrement ? 'generated-outbound' : 'outbound';
}

function isCompound(keyPath: CanaKeyPath): keyPath is readonly string[] {
  return Array.isArray(keyPath);
}

function validateKeyPath(keyPath: CanaKeyPath, where: string, problems: string[]): void {
  if (isCompound(keyPath)) {
    if (keyPath.length === 0) {
      problems.push(`${where}: compound keyPath is empty; some browsers accept this and others reject it`);
    }
    for (const segment of keyPath) {
      if (typeof segment !== 'string' || segment.length === 0) {
        problems.push(`${where}: compound keyPath contains an empty segment`);
      }
    }
    return;
  }
  if (typeof keyPath !== 'string' || keyPath.length === 0) {
    problems.push(`${where}: keyPath must be a non-empty string or an array of them`);
  }
}

function validateIndex(store: string, index: CanaIndexSchema, problems: string[]): void {
  const where = `store "${store}" index "${index.name}"`;

  if (!index.name) {
    problems.push(`store "${store}": an index has no name`);
  }

  validateKeyPath(index.keyPath, where, problems);

  if (index.multiEntry && isCompound(index.keyPath)) {
    // The rule IndexedDB enforces from inside a versionchange transaction, where
    // the failure reads as a broken upgrade rather than a bad schema.
    problems.push(
      `${where}: multiEntry cannot be combined with a compound keyPath — IndexedDB rejects it`
    );
  }
}

/**
 * Validate a schema before any database is touched.
 *
 * @returns the problems found; empty means the schema is applicable.
 */
export function validateSchema(schema: CanaSchema): readonly string[] {
  const problems: string[] = [];

  if (!Number.isInteger(schema.version) || schema.version < 1) {
    problems.push(`version must be a positive integer, received ${String(schema.version)}`);
  }

  if (schema.stores.length === 0) {
    problems.push('schema declares no stores');
  }

  const seenStores = new Set<string>();
  for (const store of schema.stores) {
    if (!store.name) {
      // Nothing further can be said about a store with no name: every remaining
      // check quotes it, and the messages would be unreadable.
      problems.push('a store has no name');
    } else {
      if (seenStores.has(store.name)) {
        problems.push(`store "${store.name}" is declared more than once`);
      }
      seenStores.add(store.name);

      if (store.keyPath !== undefined) {
        validateKeyPath(store.keyPath, `store "${store.name}"`, problems);
      }

      const seenIndexes = new Set<string>();
      for (const index of store.indexes ?? []) {
        if (seenIndexes.has(index.name)) {
          problems.push(`store "${store.name}": index "${index.name}" is declared more than once`);
        }
        seenIndexes.add(index.name);
        validateIndex(store.name, index, problems);
      }
    }
  }

  return problems;
}

/** Throw a typed failure when a schema is not applicable. */
export function assertSchema(schema: CanaSchema): void {
  const problems = validateSchema(schema);
  if (problems.length > 0) {
    throw canaError(
      'InvalidRequest',
      `Schema is not applicable:\n  - ${problems.join('\n  - ')}`
    );
  }
}

/**
 * Apply a schema inside a `versionchange` transaction.
 *
 * Deliberately additive-and-corrective rather than destructive: stores present in
 * the database but absent from the schema are **left alone**, not dropped.
 *
 * That is a real decision, not an omission. `deleteObjectStore` destroys user
 * data irreversibly, and doing it automatically because a store disappeared from
 * a schema literal means a typo silently deletes a table. Removals are therefore
 * an explicit migration step, never an inference.
 */
/** The `keyPath` shape `createObjectStore` accepts: mutable, or null for outbound. */
function domKeyPath(keyPath: CanaKeyPath | undefined): string | string[] | null {
  if (keyPath === undefined) return null;
  return isCompound(keyPath) ? [...keyPath] : keyPath;
}

export function applySchema(
  database: IDBDatabase,
  transaction: IDBTransaction,
  schema: CanaSchema
): void {
  for (const store of schema.stores) {
    const exists = database.objectStoreNames.contains(store.name);

    const objectStore = exists
      ? transaction.objectStore(store.name)
      : database.createObjectStore(store.name, {
        keyPath: domKeyPath(store.keyPath),
        autoIncrement: store.autoIncrement ?? false
      });

    const existingIndexes = new Set(Array.from(objectStore.indexNames));

    // Index definitions cannot be altered in place. Recreating one would rebuild
    // it over the whole store, which on a large table is a long blocking
    // operation inside an upgrade — so an index that already exists is left as
    // it is, and a changed definition is a migration the author must write
    // rather than something applied silently here.
    const missing = (store.indexes ?? []).filter((index) => !existingIndexes.has(index.name));

    for (const index of missing) {
      objectStore.createIndex(
        index.name,
        domKeyPath(index.keyPath) as string | string[],
        { unique: index.unique ?? false, multiEntry: index.multiEntry ?? false }
      );
    }
  }
}
/**
 * Storage durability: quota, persistence and eviction detection (JUM-560).
 *
 * Cana is offline-first, which means the browser copy is sometimes the only copy.
 * Two mechanisms take that copy away, and neither announces itself:
 *
 * 1. **Quota exhaustion** — a write fails with `QuotaExceededError`, possibly
 *    partway through a bulk.
 * 2. **Eviction** — the browser reclaims non-persisted storage under pressure, or
 *    after inactivity. No event, no error. The database is simply empty on the
 *    next open.
 *
 * Under the recorded requirement that Cana has **no fallback to localStorage**,
 * eviction is not a degradation, it is data loss. So the central problem here is
 * not quota handling. It is this:
 *
 *   **An evicted database and a brand-new one are indistinguishable by
 *   inspection. Both open empty.**
 *
 * Reporting the first as the second presents a user's lost work as a welcome
 * screen. That is the failure this module exists to make impossible.
 *
 * ## How eviction is detected
 *
 * A sentinel is written outside IndexedDB, in `localStorage`, on first successful
 * open. It records that a database of this name existed and at what version.
 *
 * `localStorage` is used **deliberately and only as a tombstone**, not as a
 * fallback store — it holds no user data, only the fact that user data once
 * existed. That distinction matters: the no-fallback requirement forbids a second
 * copy of the data, not a marker that the data was there.
 *
 * The pairing works because the two are evicted on different schedules. Browsers
 * clear IndexedDB under storage pressure far more readily than `localStorage`,
 * so "sentinel present, database empty" is a strong eviction signal.
 *
 * It is not a perfect signal, and the limits are stated rather than implied:
 *
 * - "Clear site data" removes both, so eviction becomes indistinguishable from a
 *   deliberate user reset. That is acceptable: the user did it on purpose.
 * - Private browsing gives no durable sentinel, so eviction cannot be detected
 *   there. Also acceptable: private sessions are `Unavailable` territory anyway.
 * - A user who clears only IndexedDB via devtools is reported as evicted. Correct
 *   for our purposes — their data is in fact gone.
 */

import type { CanaStorageState } from '../contracts';

/** Default headroom at which `nearQuota` flips, as a fraction of quota. */
const DEFAULT_NEAR_QUOTA_RATIO = 0.85;

const SENTINEL_PREFIX = 'cana.existed.v1:';

/**
 * The environment capabilities this module needs, injected rather than reached
 * for, so the logic is testable without a browser.
 */
export interface StorageEnvironment {
  /** `navigator.storage`, when present. */
  readonly estimate?: () => Promise<{ usage?: number; quota?: number }>;
  readonly persist?: () => Promise<boolean>;
  readonly persisted?: () => Promise<boolean>;
  /** Durable key/value used only for the existence tombstone. */
  readonly tombstone?: {
    get(key: string): string | null;
    set(key: string, value: string): void;
    remove(key: string): void;
  };
}

export interface DatabaseObservation {
  readonly databaseName: string;
  /**
   * Version found before opening: 0 when the database did not exist, and
   * `undefined` when the engine could not determine it.
   *
   * The three-way distinction is load-bearing. `IDBFactory.databases()` is not
   * universally available — Safari lacked it for years — and an implementation
   * that reports "cannot tell" as 0 turns every open in those browsers into
   * "the database is gone", which classifies healthy populated databases as
   * evicted. Absence and ignorance are different facts.
   */
  readonly foundVersion: number | undefined;
  /** True when the opened database contains no records in any store. */
  readonly isEmpty: boolean;
}

export interface EvictionVerdict {
  readonly evicted: boolean;
  /**
   * Why the verdict was reached, so a consumer can surface something specific
   * instead of a generic warning.
   */
  readonly reason:
    | 'first-run'
    | 'existing-data'
    | 'evicted-database-absent'
    | 'evicted-database-empty'
    | 'undetectable-no-tombstone';
}

function sentinelKey(databaseName: string): string {
  return `${SENTINEL_PREFIX}${databaseName}`;
}

/**
 * Decide whether a database that opened empty was evicted or simply new.
 *
 * Pure, so the decision table is testable exhaustively rather than by luck.
 */
/**
 * Whether the tombstone records that this database was ever seen holding data.
 *
 * A stored flag rather than an inference, because `isEmpty` at open time cannot
 * distinguish "wiped" from "never written to". Tombstones written before this
 * field existed read as false, which errs towards not claiming a loss.
 */
function recordedData(tombstoneValue: string | null): boolean {
  if (tombstoneValue === null) return false;
  try {
    return (JSON.parse(tombstoneValue) as { hadData?: unknown }).hadData === true;
  } catch {
    return false;
  }
}

export function classifyOpen(
  observation: DatabaseObservation,
  tombstoneValue: string | null
): EvictionVerdict {
  const hadDatabaseBefore = tombstoneValue !== null;

  if (!hadDatabaseBefore) {
    // No record of a previous life. Either genuinely first run, or a session
    // where no durable marker is available at all — the caller distinguishes
    // those via `recordExistence` returning false.
    return { evicted: false, reason: 'first-run' };
  }

  if (observation.foundVersion === 0) {
    // We know it existed, and now it is not there at all.
    return { evicted: true, reason: 'evicted-database-absent' };
  }

  // `undefined` means the pre-open probe could not answer, not that the database
  // was missing. Falling through to the contents check is the only sound move:
  // claiming eviction on an unanswered question would report loss every time in
  // any browser without `databases()`.

  if (observation.isEmpty && !recordedData(tombstoneValue)) {
    // Present and empty, and we have no record that it ever held anything. This
    // is the ordinary case of a user who opened the app and has not written
    // anything yet — reporting it as eviction would tell them they lost data
    // they never had, which is exactly as damaging as missing a real loss.
    return { evicted: false, reason: 'existing-data' };
  }

  if (observation.isEmpty) {
    // The database exists but is empty, and we know it held data before. Some
    // browsers recreate the store shell while dropping contents.
    return { evicted: true, reason: 'evicted-database-empty' };
  }

  return { evicted: false, reason: 'existing-data' };
}

export class StorageDurability {
  private readonly environment: StorageEnvironment;

  private readonly nearQuotaRatio: number;

  private evictedFlag = false;

  private lastVerdict: EvictionVerdict | null = null;

  constructor(environment: StorageEnvironment, nearQuotaRatio = DEFAULT_NEAR_QUOTA_RATIO) {
    this.environment = environment;
    this.nearQuotaRatio = nearQuotaRatio;
  }

  /**
   * Ask for persistent storage.
   *
   * Returns `'unknown'` rather than `false` when the API is absent. Those are
   * genuinely different: `false` means the browser refused, `'unknown'` means we
   * cannot claim durability either way — and flattening the second into the first
   * would let an application report a guarantee it does not have.
   */
  async requestPersistence(): Promise<boolean | 'unknown'> {
    const { persist, persisted } = this.environment;
    if (!persist && !persisted) {
      return 'unknown';
    }

    try {
      if (persisted) {
        const already = await persisted();
        if (already) return true;
      }
      if (persist) {
        return await persist();
      }
      return 'unknown';
    } catch {
      return 'unknown';
    }
  }

  /**
   * Record that this database exists, so a later empty open is recognisable as
   * eviction.
   *
   * @returns false when no durable marker could be written, which means eviction
   *   will be undetectable for this origin. The caller is expected to surface
   *   that rather than assume detection works.
   */
  recordExistence(databaseName: string, version: number, hadData = false): boolean {
    const { tombstone } = this.environment;
    if (!tombstone) return false;
    try {
      // `hadData` is sticky: once this database has been seen holding records, a
      // later empty open is a loss rather than a fresh start. Clearing it on an
      // empty open would erase the only evidence eviction is detectable by.
      const seenData = hadData || recordedData(this.readTombstone(databaseName));
      tombstone.set(
        sentinelKey(databaseName),
        JSON.stringify({ version, at: Date.now(), hadData: seenData })
      );
      return true;
    } catch {
      // Private browsing throws on write in some browsers. Undetectable, not fatal.
      return false;
    }
  }

  /** Read the raw tombstone, treating any failure to read as absent. */
  private readTombstone(databaseName: string): string | null {
    const { tombstone } = this.environment;
    if (!tombstone) return null;
    try {
      return tombstone.get(sentinelKey(databaseName));
    } catch {
      return null;
    }
  }

  /** Evaluate an open against the tombstone. Records the verdict for `state()`. */
  evaluateOpen(observation: DatabaseObservation): EvictionVerdict {
    const { tombstone } = this.environment;

    if (!tombstone) {
      const verdict: EvictionVerdict = { evicted: false, reason: 'undetectable-no-tombstone' };
      this.lastVerdict = verdict;
      return verdict;
    }

    const verdict = classifyOpen(observation, this.readTombstone(observation.databaseName));
    this.lastVerdict = verdict;
    this.evictedFlag = verdict.evicted;
    return verdict;
  }

  /** Clear the eviction flag once the consumer has acknowledged the loss. */
  acknowledgeEviction(): void {
    this.evictedFlag = false;
  }

  get lastEvictionVerdict(): EvictionVerdict | null {
    return this.lastVerdict;
  }

  /** Current durability state, for `CanaClient.storageState()`. */
  async state(): Promise<CanaStorageState> {
    const persistent = await this.currentPersistence();
    const { usageBytes, quotaBytes } = await this.currentUsage();

    const nearQuota = usageBytes !== undefined
      && quotaBytes !== undefined
      && quotaBytes > 0
      && usageBytes / quotaBytes >= this.nearQuotaRatio;

    return {
      persistent,
      usageBytes,
      quotaBytes,
      nearQuota,
      evicted: this.evictedFlag
    };
  }

  private async currentPersistence(): Promise<boolean | 'unknown'> {
    const { persisted } = this.environment;
    if (!persisted) return 'unknown';
    try {
      return await persisted();
    } catch {
      return 'unknown';
    }
  }

  private async currentUsage(): Promise<{ usageBytes?: number; quotaBytes?: number }> {
    const { estimate } = this.environment;
    if (!estimate) return {};
    try {
      const result = await estimate();
      return { usageBytes: result.usage, quotaBytes: result.quota };
    } catch {
      return {};
    }
  }
}

/**
 * Build the environment from real browser globals.
 *
 * Kept separate from the class so every test path can inject a fake and the
 * browser-only reach happens in exactly one place.
 */
export function browserStorageEnvironment(): StorageEnvironment {
  const nav = typeof navigator === 'undefined' ? undefined : navigator;
  const storage = nav?.storage;
  const local = typeof localStorage === 'undefined' ? undefined : localStorage;

  return {
    estimate: storage?.estimate ? () => storage.estimate() : undefined,
    persist: storage?.persist ? () => storage.persist() : undefined,
    persisted: storage?.persisted ? () => storage.persisted() : undefined,
    tombstone: local
      ? {
        get: (key) => local.getItem(key),
        set: (key, value) => local.setItem(key, value),
        remove: (key) => local.removeItem(key)
      }
      : undefined
  };
}
/**
 * Database lifecycle: open, upgrade, close, delete (JUM-403).
 *
 * First engine task deliberately, because this is where offline-first products
 * lose data. An IndexedDB upgrade runs inside a `versionchange` transaction the
 * browser controls; if it fails partway the database is left at an indeterminate
 * version with partially-applied schema changes, and unlike a server database
 * there is no operator to repair it.
 *
 * Three behaviours here are decisions rather than mechanics:
 *
 * 1. **A blocked upgrade times out instead of hanging forever.** `onblocked`
 *    fires when another tab holds an old connection open. The naive
 *    implementation waits indefinitely and the application simply never
 *    finishes starting — a hang is worse than an error, because an error can be
 *    displayed.
 *
 * 2. **A downgrade is refused, not attempted.** IndexedDB throws `VersionError`
 *    for a lower version, but the useful part is saying *why*: an older build of
 *    the app opened a database written by a newer one, which is routine when a
 *    user has two tabs across a deploy.
 *
 * 3. **Eviction is evaluated on every open.** The engine cannot tell an evicted
 *    database from a new one by inspection — both open empty — so it consults
 *    the durability tombstone before reporting anything to the caller. See
 *    `storage.ts`.
 */

import type { CanaSchema } from '../contracts';
import { canaError, requestToPromise, translateError } from './errors';
import { applySchema, assertSchema } from './schema';
import type { EvictionVerdict } from './storage';
import { StorageDurability, browserStorageEnvironment } from './storage';

export interface OpenOptions {
  readonly name: string;
  readonly schema: CanaSchema;
  /** How long to wait for another connection to release a version change. */
  readonly blockedTimeoutMs?: number;
  /** Injected so the engine is testable without a browser global. */
  readonly factory?: IDBFactory;
  readonly durability?: StorageDurability;
}

export interface OpenResult {
  readonly database: IDBDatabase;
  readonly eviction: EvictionVerdict;
  /** True when this open ran an upgrade. */
  readonly upgraded: boolean;
}

const DEFAULT_BLOCKED_TIMEOUT_MS = 10_000;

function resolveFactory(explicit?: IDBFactory): IDBFactory {
  if (explicit) return explicit;
  if (typeof indexedDB !== 'undefined' && indexedDB) return indexedDB;
  throw canaError(
    'Unavailable',
    'No usable IndexedDB in this environment. Private browsing or an unsupported '
      + 'browser — there is no fallback store, so this is terminal rather than degraded.'
  );
}

/**
 * Read the current version without triggering an upgrade.
 *
 * Returns 0 when the database is genuinely absent, and `undefined` when the
 * question could not be answered at all. Collapsing the second into the first is
 * precisely the bug this signature exists to prevent: `databases()` is not
 * universally available — Safari lacked it for years — and reporting ignorance
 * as absence makes the eviction classifier declare every healthy, populated
 * database evicted in those browsers.
 */
async function currentVersion(factory: IDBFactory, name: string): Promise<number | undefined> {
  if (typeof factory.databases !== 'function') return undefined;
  try {
    const listed = await factory.databases();
    const match = listed.find((entry) => entry.name === name);
    return match?.version ?? 0;
  } catch {
    return undefined;
  }
}

/** True when every store in the database is empty. */
async function isDatabaseEmpty(database: IDBDatabase): Promise<boolean> {
  const names = Array.from(database.objectStoreNames);
  if (names.length === 0) return true;

  const transaction = database.transaction(names, 'readonly');
  for (const name of names) {
    // Sequential on purpose: the transaction's auto-commit window stays open
    // only while requests are outstanding, and interleaving awaits from other
    // sources here is exactly how it closes underneath you.
    // eslint-disable-next-line no-await-in-loop
    const count = await requestToPromise(transaction.objectStore(name).count(), { store: name });
    if (count > 0) return false;
  }
  return true;
}

/**
 * Open a database, applying the schema when the version requires it.
 *
 * Rejects with a `CanaError`; no `DOMException` escapes.
 */
export async function openDatabase(options: OpenOptions): Promise<OpenResult> {
  assertSchema(options.schema);

  const factory = resolveFactory(options.factory);
  // The real browser environment by default. An empty one writes no tombstone,
  // which silently disables eviction detection entirely (JUM-560).
  const durability = options.durability ?? new StorageDurability(browserStorageEnvironment());
  const blockedTimeoutMs = options.blockedTimeoutMs ?? DEFAULT_BLOCKED_TIMEOUT_MS;

  const existingVersion = await currentVersion(factory, options.name);
  if (existingVersion !== undefined && existingVersion > options.schema.version) {
    throw canaError(
      'UpgradeFailed',
      `Refusing to downgrade "${options.name}" from version ${existingVersion} to `
        + `${options.schema.version}. A newer build of the application wrote this database; `
        + 'downgrades are not attempted because they cannot be made safe.'
    );
  }

  let upgraded = false;
  let upgradeFailure: unknown;

  const database = await new Promise<IDBDatabase>((resolve, reject) => {
    let settled = false;
    const request = factory.open(options.name, options.schema.version);

    const blockedTimer = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(canaError(
        'UpgradeBlocked',
        `Upgrading "${options.name}" is blocked by another open connection and did not `
          + `clear within ${blockedTimeoutMs}ms. Another tab is holding the previous version.`
      ));
    }, blockedTimeoutMs);

    const finish = (action: () => void) => {
      if (settled) {
        // The timeout already rejected, and the open then succeeded anyway. The
        // connection is live and nobody holds a reference to it, so it must be
        // closed here: an orphaned IDBDatabase goes on blocking version changes
        // in this tab, which is precisely the state the timeout existed to
        // escape. Leaving it open turns a recoverable timeout into a permanent
        // block that no later call can clear.
        request.result?.close();
        return;
      }
      settled = true;
      clearTimeout(blockedTimer);
      action();
    };

    request.onupgradeneeded = () => {
      upgraded = true;
      const { transaction } = request;
      if (!transaction) {
        upgradeFailure = canaError('UpgradeFailed', 'Upgrade started without a transaction.');
        return;
      }
      try {
        applySchema(request.result, transaction, options.schema);
      } catch (error) {
        // Record and abort rather than throw: throwing here is swallowed by the
        // DOM event handler, and the open would resolve with a half-applied
        // schema — the indeterminate state this task exists to prevent.
        upgradeFailure = translateError(error);
        transaction.abort();
      }
    };

    request.onsuccess = () => finish(() => {
      if (upgradeFailure !== undefined) {
        request.result.close();
        reject(translateError(upgradeFailure));
        return;
      }
      resolve(request.result);
    });

    request.onerror = () => finish(() => {
      reject(upgradeFailure !== undefined
        ? translateError(upgradeFailure)
        : translateError(request.error, {}));
    });

    request.onblocked = () => {
      // Leave the timer running; this only tells us why we are waiting.
    };
  });

  // Where the pre-open probe could not answer, the open itself supplies part of
  // the answer: if no upgrade ran, the database already existed at this version,
  // so it is certainly not absent. This recovers the common case in browsers
  // without `databases()` instead of leaving every open unclassifiable.
  const observedVersion = existingVersion ?? (upgraded ? undefined : database.version);

  // Only now, with a live connection, can eviction be judged: it needs both the
  // tombstone and the observed contents.
  const isEmpty = await isDatabaseEmpty(database);

  const eviction = durability.evaluateOpen({
    databaseName: options.name,
    foundVersion: observedVersion,
    isEmpty
  });

  // `hadData` is what lets a later empty open be told apart from a database that
  // was simply never written to. Recorded the first time records are actually
  // observed; the flag is sticky from then on.
  durability.recordExistence(options.name, options.schema.version, !isEmpty);

  return { database, eviction, upgraded };
}

export function closeDatabase(database: IDBDatabase): void {
  database.close();
}

/** Delete a database, refusing to hang when another connection blocks it. */
export async function deleteDatabase(
  name: string,
  options: { factory?: IDBFactory; blockedTimeoutMs?: number } = {}
): Promise<void> {
  const factory = resolveFactory(options.factory);
  const blockedTimeoutMs = options.blockedTimeoutMs ?? DEFAULT_BLOCKED_TIMEOUT_MS;

  await new Promise<void>((resolve, reject) => {
    let settled = false;
    const request = factory.deleteDatabase(name);

    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(canaError(
        'UpgradeBlocked',
        `Deleting "${name}" is blocked by another open connection.`
      ));
    }, blockedTimeoutMs);

    const finish = (action: () => void) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      action();
    };

    request.onsuccess = () => finish(resolve);
    request.onerror = () => finish(() => reject(translateError(request.error)));
  });
}
/**
 * Resolving the `unknown` write outcome (JUM-559, JUM-411).
 *
 * `unknown` is honest but useless on its own. A caller told "your write may or
 * may not have landed" has two bad options: retry, and risk duplicating it; or
 * skip, and risk losing it. Reporting the ambiguity is better than lying about
 * it, but the ambiguity still has to be resolved by someone.
 *
 * This resolves it, using the one thing IndexedDB actually guarantees: a
 * transaction is atomic. So the operation id is written **into the same
 * transaction as the data**. There is no window between them — the store cannot
 * commit one and not the other.
 *
 * Afterwards the question "did my write commit?" becomes a lookup:
 *
 *   ledger contains the id  ->  it committed
 *   ledger does not         ->  it did not
 *
 * That holds across a killed worker, a closed tab, or a browser that was
 * force-quit mid-flush, because it does not depend on anything in memory
 * surviving. It is the reason `CanaWriteOutcome` has three states rather than a
 * boolean and a shrug.
 *
 * The ledger is pruned by age. An unbounded one grows forever; a pruned one can
 * only answer about recent operations, and `resolveOutcome` says
 * `'unresolvable'` past the horizon rather than inferring `'rolled-back'` from
 * an absence it cannot distinguish from a deletion.
 */

import type { CanaWriteOutcome } from '../contracts';
import { requestToPromise } from './errors';

/** The store the ledger lives in. Present in every Cana schema. */
export const OPERATION_LEDGER_STORE = '__cana_operations';

export interface OperationRecord {
  readonly id: string;
  readonly at: number;
  readonly stores: readonly string[];
}

/** How long a completed operation stays answerable. */
export const DEFAULT_LEDGER_HORIZON_MS = 24 * 60 * 60 * 1000;

/**
 * The outcome of a resolution attempt.
 *
 * `unresolvable` is separate from `rolled-back` on purpose. Both look like "the
 * id is not there", but one means the write definitely did not happen and the
 * other means the evidence has been pruned. Collapsing them would turn a
 * committed-but-forgotten write into a confident "it did not commit", which is
 * exactly the duplicate-write bug this file exists to prevent.
 */
export type ResolvedOutcome =
  | Extract<CanaWriteOutcome, 'committed' | 'rolled-back'>
  | 'unresolvable';

/** The ledger's own store declaration, in the shape a Cana schema expects. */
interface LedgerStoreSchema {
  name: string;
  keyPath: string;
  indexes: { name: string; keyPath: string }[];
}

/** Add the ledger store to a schema's store list if it is not already there. */
export function withLedgerStore<TStore extends { name: string }>(
  stores: readonly TStore[]
): readonly (TStore | LedgerStoreSchema)[] {
  if (stores.some((store) => store.name === OPERATION_LEDGER_STORE)) return stores;
  return [
    ...stores,
    {
      name: OPERATION_LEDGER_STORE,
      keyPath: 'id',
      // Indexed by time so pruning is a bounded range delete rather than a scan
      // of every operation ever recorded.
      indexes: [{ name: 'byTime', keyPath: 'at' }]
    }
  ];
}

/**
 * Record an operation id inside a transaction that is already in progress.
 *
 * Must be called with a transaction whose scope includes the ledger store, and
 * the same one the data is written in — that shared transaction is the entire
 * guarantee. Recording it separately afterwards would reintroduce the window
 * this is meant to close.
 */
export function recordOperation(
  transaction: IDBTransaction,
  operation: OperationRecord
): Promise<IDBValidKey> {
  return requestToPromise(
    transaction.objectStore(OPERATION_LEDGER_STORE).put({ ...operation }),
    { store: OPERATION_LEDGER_STORE }
  );
}

/**
 * Ask whether an operation committed.
 *
 * `attemptedAt` is required, and it is the whole reason this can answer at all.
 * A missing id means one of two very different things — the write never
 * committed, or its record was pruned — and nothing in the ledger itself can
 * tell them apart, precisely because the evidence is what is missing. Knowing
 * when the operation was attempted does distinguish them:
 *
 *   attempted inside the horizon  ->  the record would still be here if it had
 *                                     committed, so it did not: 'rolled-back'
 *   attempted before the horizon  ->  a committed record could have been pruned
 *                                     by now: 'unresolvable'
 *
 * The caller has `attemptedAt` because it is the one that issued the write and
 * had to persist the pending operation somewhere to be asking this at all.
 */
export async function resolveOutcome(
  database: IDBDatabase,
  operationId: string,
  attemptedAt: number,
  options: { horizonMs?: number; now?: number } = {}
): Promise<ResolvedOutcome> {
  const horizonMs = options.horizonMs ?? DEFAULT_LEDGER_HORIZON_MS;
  const now = options.now ?? Date.now();

  if (!database.objectStoreNames.contains(OPERATION_LEDGER_STORE)) {
    // No ledger means no evidence either way. Saying 'rolled-back' here would be
    // a guess dressed as a fact.
    return 'unresolvable';
  }

  const transaction = database.transaction(OPERATION_LEDGER_STORE, 'readonly');
  const found = await requestToPromise<OperationRecord | undefined>(
    transaction.objectStore(OPERATION_LEDGER_STORE).get(operationId) as IDBRequest<
      OperationRecord | undefined
    >,
    { store: OPERATION_LEDGER_STORE }
  );

  if (found) return 'committed';

  return now - attemptedAt > horizonMs ? 'unresolvable' : 'rolled-back';
}

/**
 * Delete ledger entries older than the horizon.
 *
 * A bounded range delete over the time index, not a scan: the ledger is written
 * on every transaction, so pruning it must not cost more than the writes do.
 */
export async function pruneLedger(
  database: IDBDatabase,
  options: { horizonMs?: number; now?: number } = {}
): Promise<number> {
  const horizonMs = options.horizonMs ?? DEFAULT_LEDGER_HORIZON_MS;
  const now = options.now ?? Date.now();
  const cutoff = now - horizonMs;

  if (!database.objectStoreNames.contains(OPERATION_LEDGER_STORE)) return 0;

  const transaction = database.transaction(OPERATION_LEDGER_STORE, 'readwrite');
  const index = transaction.objectStore(OPERATION_LEDGER_STORE).index('byTime');

  return new Promise<number>((resolve, reject) => {
    let removed = 0;
    const request = index.openCursor(IDBKeyRange.upperBound(cutoff, true));
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve(removed);
        return;
      }
      cursor.delete();
      removed += 1;
      cursor.continue();
    };
    request.onerror = () => reject(request.error);
  });
}
/**
 * The client surface (JUM-405, JUM-407, JUM-412, JUM-413).
 *
 * Assembles lifecycle, transactions, tables and change notification into the
 * `CanaClient` contract. Three things here are decisions rather than plumbing.
 *
 * **Single-operation calls get their own transaction.** `client.table('x').put(r)`
 * opens a transaction, writes, commits, and reports the outcome. It is not a
 * shortcut into a shared ambient transaction, because an ambient one would make
 * the durability of any single call depend on unrelated code elsewhere.
 *
 * **Listeners are called in registration order, and one throwing does not stop
 * the rest** (JUM-413). A subscriber that fails is a bug in that subscriber; if
 * it silently prevented later subscribers from ever seeing the event, the
 * resulting inconsistency would appear far from its cause.
 *
 * **`sinceCursor` replays.** A subscriber that was absent — a worker that
 * restarted, a tab that was backgrounded — resumes from its last cursor rather
 * than starting from now and silently missing the gap. The retained window is
 * bounded, and when a requested cursor has fallen out of it the client says so
 * instead of pretending the replay was complete.
 */

import type {
  CanaChangeEvent,
  CanaClient,
  CanaKey,
  CanaSchema,
  CanaStorageState,
  CanaTable,
  CanaTransactionMode,
  CanaTransactionResult,
  CanaTransactionScope,
  CanaWriteOutcome
} from '../contracts';
import { isCanaError } from '../contracts';
import { canaError } from './errors';
import type { DurabilityAssessment, DurabilityPolicy } from './durability-policy';
import { DEFAULT_DURABILITY_POLICY, assessDurability } from './durability-policy';
import type { CanaHooks } from './hooks';
import { notifyCommitted, notifyRolledBack } from './hooks';
import { openDatabase } from './database';
import {
  OPERATION_LEDGER_STORE,
  recordOperation,
  resolveOutcome,
  withLedgerStore
} from './reconciliation';
import type { ResolvedOutcome } from './reconciliation';
import { StorageDurability, browserStorageEnvironment } from './storage';
import { createTable } from './table';
import { abortWithReason, createChangeBuffer, runTransaction } from './transaction';

export interface ClientOptions {
  readonly name: string;
  readonly schema: CanaSchema;
  readonly factory?: IDBFactory;
  readonly durability?: StorageDurability;
  /** How many committed events stay replayable. */
  readonly retainedEvents?: number;
  /** Identifies this client in events, so a subscriber can ignore its own writes. */
  readonly originId?: string;
  readonly hooks?: CanaHooks;
  readonly durabilityPolicy?: DurabilityPolicy;
  /**
   * Record every write transaction in the operation ledger so an interrupted
   * write can be resolved after a crash. Off by default: it costs one extra
   * request per transaction, which only pays for itself when a worker or tab
   * can actually die mid-write (JUM-559).
   */
  readonly operationLedger?: boolean;
}

/**
 * Bounded on purpose. An unbounded history is a memory leak in a long-lived tab,
 * and the alternative — dropping the oldest silently — is why `subscribe`
 * reports a cursor it can no longer honour rather than replaying a partial gap.
 */
const DEFAULT_RETAINED_EVENTS = 1000;

interface Subscription {
  readonly listener: (event: CanaChangeEvent) => void;
  active: boolean;
}

/**
 * The only thing the auto-commit table needs from a client.
 *
 * Narrowed to this rather than the concrete class so the dependency runs one
 * way: the table knows how to start a transaction and nothing else about who
 * owns it.
 */
interface TransactionRunner {
  transaction<TResult>(
    mode: CanaTransactionMode,
    stores: readonly string[],
    body: (scope: CanaTransactionScope) => Promise<TResult> | TResult
  ): Promise<CanaTransactionResult<TResult>>;
}

/**
 * A table outside any explicit transaction: each call gets its own.
 *
 * Deliberately a distinct implementation rather than the transactional table
 * with a nullable transaction, so "am I inside a transaction?" is never a
 * runtime question — the two cases are different objects with the same surface.
 */
function createAutoCommitTable<TRecord, TKey extends CanaKey = CanaKey>(
  name: string,
  client: TransactionRunner
): CanaTable<TRecord, TKey> {
  type Bound = CanaTable<TRecord, TKey>;

  const read = <TResult>(body: (table: Bound) => Promise<TResult>): Promise<TResult> => client
    .transaction('readonly', [name], (scope) => body(scope.table<TRecord, TKey>(name)))
    .then(({ result }) => result as TResult);

  const write = <TResult extends { outcome: CanaWriteOutcome }>(
    body: (table: Bound) => Promise<TResult>
  ): Promise<TResult> => client
      .transaction('readwrite', [name], (scope) => body(scope.table<TRecord, TKey>(name)))
    // The per-operation result reports `committed` optimistically; the
    // transaction's own outcome is the authoritative one, and the events only
    // exist at all if it committed.
      .then(({ outcome, result, events }) => ({ ...(result as TResult), outcome, events }));

  return {
    name,
    get: (key) => read((table) => table.get(key)),
    count: (query) => read((table) => table.count(query)),
    query: (query) => read((table) => table.query(query)),
    explain: (query) => read((table) => table.explain(query)),
    add: (record, key) => write((table) => table.add(record, key)),
    put: (record, key) => write((table) => table.put(record, key)),
    update: (key, changes) => write((table) => table.update(key, changes)),
    delete: (key) => write((table) => table.delete(key)),
    clear: () => write((table) => table.clear()),
    bulkAdd: (records) => write((table) => table.bulkAdd(records)),
    bulkPut: (records) => write((table) => table.bulkPut(records)),
    bulkDelete: (keys) => write((table) => table.bulkDelete(keys))
  };
}

export class Client implements CanaClient {
  readonly name: string;

  readonly version: number;

  private database?: IDBDatabase;

  private readonly durability: StorageDurability;

  private readonly history: CanaChangeEvent[] = [];

  private readonly subscriptions: Subscription[] = [];

  private readonly originId: string;

  private readonly retainedEvents: number;

  private cursor = 0;

  private correlation = 0;

  constructor(private readonly options: ClientOptions) {
    this.name = options.name;
    this.version = options.schema.version;
    // Defaults to the real browser environment, not an empty one. An empty
    // environment writes no tombstone, so `recordExistence` always fails and
    // eviction stays 'undetectable-no-tombstone' forever — JUM-560's detection
    // was documented but, by default, switched off.
    this.durability = options.durability ?? new StorageDurability(browserStorageEnvironment());
    this.retainedEvents = options.retainedEvents ?? DEFAULT_RETAINED_EVENTS;
    // `crypto.randomUUID()`, not `Math.random()`. The origin id is what tells a
    // subscriber which tab produced a change, so a collision makes one tab's
    // writes look like its own echo and the event is dropped. `Math.random` gives
    // no collision guarantee, and eight base-36 characters make one plausible
    // across enough tabs and reloads. `crypto` is available in every browser
    // Cana targets and in Bun.
    this.originId = options.originId ?? `cana-${crypto.randomUUID()}`;
  }

  /**
   * The schema as it will actually be applied.
   *
   * When the ledger is enabled its store is added here rather than being left to
   * the application to declare, because forgetting it would mean the ledger
   * silently records nothing and the crash-resolution path reports
   * `unresolvable` forever without saying why.
   */
  private effectiveSchema(): CanaSchema {
    if (!this.options.operationLedger) return this.options.schema;
    return {
      ...this.options.schema,
      stores: withLedgerStore(this.options.schema.stores) as CanaSchema['stores']
    };
  }

  async open(): Promise<void> {
    if (this.database) return;
    const opened = await openDatabase({
      name: this.options.name,
      schema: this.effectiveSchema(),
      durability: this.durability,
      ...(this.options.factory === undefined ? {} : { factory: this.options.factory })
    });
    this.database = opened.database;

    // Enabling the ledger adds its store to the schema, but IndexedDB only runs
    // an upgrade when the version increases. Turning `operationLedger` on
    // against an existing database at the same version therefore creates no
    // store — and the previous code then quietly disabled the ledger, so writes
    // recorded nothing and `resolveWrite` answered `unresolvable` forever with
    // no indication why. That is exactly the silent no-op the ledger exists to
    // rule out, so it now fails loudly and says what to do.
    if (this.options.operationLedger
      && !opened.database.objectStoreNames.contains(OPERATION_LEDGER_STORE)) {
      opened.database.close();
      this.database = undefined;
      throw canaError(
        'UpgradeFailed',
        `The operation ledger is enabled for "${this.name}" but its store does not exist. The `
          + `database is already at version ${this.version}, and IndexedDB applies schema changes `
          + 'only when the version increases. Raise the schema version so the ledger store can be '
          + 'created — leaving it as-is would record nothing and make every crash unresolvable.'
      );
    }

    // Asked for only when the application opted in. A persistence prompt fired
    // by a library at an arbitrary moment is one the user denies, and some
    // browsers make that denial sticky for the origin.
    if (this.options.durabilityPolicy?.requestPersistenceOnOpen
      ?? DEFAULT_DURABILITY_POLICY.requestPersistenceOnOpen) {
      await this.durability.requestPersistence();
    }
  }

  /**
   * What the application is allowed to tell its user about durability.
   *
   * Separate from `storageState()`, which reports raw observations: this applies
   * the policy that refuses to round 'unknown' up to 'durable' (JUM-415).
   */
  async durabilityAssessment(): Promise<DurabilityAssessment> {
    const current = await this.durability.state();
    return assessDurability(current, this.durability.lastEvictionVerdict);
  }

  async close(): Promise<void> {
    this.database?.close();
    this.database = undefined;
  }

  private requireOpen(): IDBDatabase {
    if (!this.database) {
      throw canaError(
        'InvalidRequest',
        `Client for "${this.name}" is not open. Call open() before using it — the engine does not `
          + 'open implicitly, because an implicit open hides an upgrade behind an unrelated call.'
      );
    }
    return this.database;
  }

  private nextCursor = (): number => {
    this.cursor += 1;
    return this.cursor;
  };

  /**
   * Retain for replay, then notify. That order matters: a listener that throws
   * must not cost the event its place in the replayable history.
   */
  private publish(events: readonly CanaChangeEvent[]): void {
    if (events.length === 0) return;

    this.history.push(...events);
    if (this.history.length > this.retainedEvents) {
      this.history.splice(0, this.history.length - this.retainedEvents);
    }

    for (const event of events) {
      for (const subscription of [...this.subscriptions].filter((entry) => entry.active)) {
        try {
          subscription.listener(event);
        } catch {
          // A failing subscriber is that subscriber's bug. Letting it stop
          // delivery to the others would turn one broken listener into a
          // database-wide inconsistency reported nowhere near its cause.
        }
      }
    }
  }

  table<TRecord, TKey extends CanaKey = CanaKey>(name: string): CanaTable<TRecord, TKey> {
    return createAutoCommitTable<TRecord, TKey>(name, this);
  }

  /**
   * Resolve a write whose outcome was reported as `unknown` (JUM-559).
   *
   * The answer comes from the operation ledger, which was written inside the
   * same transaction as the data — so it survives a killed worker, a closed tab
   * or a force-quit browser, none of which preserve anything in memory.
   *
   * Requires `operationLedger: true`; without it there is no evidence and the
   * answer is `unresolvable` rather than a guess.
   */
  resolveWrite(
    correlationId: string,
    attemptedAt: number,
    options: { horizonMs?: number; now?: number } = {}
  ): Promise<ResolvedOutcome> {
    return resolveOutcome(this.requireOpen(), correlationId, attemptedAt, options);
  }

  async transaction<TResult>(
    mode: CanaTransactionMode,
    stores: readonly string[],
    body: (scope: CanaTransactionScope) => Promise<TResult> | TResult
  ): Promise<CanaTransactionResult<TResult>> {
    const database = this.requireOpen();
    const buffer = createChangeBuffer(this.nextCursor, this.originId);
    this.correlation += 1;
    const correlationId = `${this.originId}:${this.correlation}`;

    const { hooks } = this.options;

    // The ledger store joins the transaction's scope, so the operation id and
    // the data commit or roll back together. Recording it in a second
    // transaction would leave exactly the window this is meant to close.
    // `open()` already guaranteed the store exists whenever the ledger is on, so
    // this no longer silently degrades when it is missing.
    const ledgered = this.options.operationLedger === true && mode === 'readwrite';

    const scope = ledgered && !stores.includes(OPERATION_LEDGER_STORE)
      ? [...stores, OPERATION_LEDGER_STORE]
      : stores;

    const attemptedAt = Date.now();

    let outcome;
    try {
      outcome = await runTransaction<TResult>({
        database,
        stores: scope,
        mode,
        buffer,
        body: async (transaction) => {
          // Recorded FIRST, before the body runs.
          //
          // An earlier version recorded it last, reasoning that an abort must
          // never leave an id claiming a commit. That reasoning was redundant —
          // the shared transaction already guarantees the row rolls back with
          // the data — and it broke the one case the ledger exists for: if the
          // body writes, IndexedDB auto-commits, and the body then throws, the
          // transaction commits with no ledger row. `resolveWrite` would see a
          // missing id inside the horizon and answer 'rolled-back' for data that
          // is on disk, which is exactly the unsafe-retry it was built to
          // prevent. Recording first is safe in both directions.
          if (ledgered) {
            await recordOperation(transaction, {
              id: correlationId,
              at: attemptedAt,
              stores: [...stores]
            });
          }

          return body({
            table: <TRecord, TKey extends CanaKey = CanaKey>(
              name: string
            ) => createTable<TRecord, TKey>(
              name,
              {
                transaction,
                buffer,
                correlationId,
                ...(hooks === undefined ? {} : { hooks })
              }
            ),
            abort: (reason?: string) => abortWithReason(transaction, reason)
          });
        }
      });
    } catch (error: unknown) {
      // Every throw out of `runTransaction` means nothing was committed, so the
      // hook is told before the failure propagates. It cannot suppress it.
      notifyRolledBack(hooks, 'rolled-back', isCanaError(error) ? error.message : undefined);
      throw error;
    }

    if (outcome.outcome !== 'committed') {
      // Reached only for `unknown` — the body failed but the transaction had
      // already auto-committed. This is the case that needs reconciliation, and
      // it is reported as itself rather than folded into a rollback.
      notifyRolledBack(hooks, 'unknown');
      // Carries the id and timestamp, because this is the outcome a caller must
      // reconcile — and reconciling means calling resolveWrite with exactly
      // these two values.
      return { ...outcome, correlationId, attemptedAt };
    }

    // Only committed transactions produce events; `runTransaction` discards the
    // buffer on every other path.
    this.publish(outcome.events);
    notifyCommitted(hooks, outcome.events);
    return { ...outcome, correlationId, attemptedAt };
  }

  storageState(): Promise<CanaStorageState> {
    return this.durability.state();
  }

  subscribe(
    listener: (event: CanaChangeEvent) => void,
    options: { sinceCursor?: number } = {}
  ): () => void {
    const since = options.sinceCursor;

    // Validated BEFORE registering. Registering first and then throwing left an
    // inactive entry in the array with no unsubscribe function to remove it, so
    // every refused subscribe leaked one permanently — and a caller retrying in
    // a loop would grow the list without bound.
    if (since !== undefined) {
      const oldest = this.history[0]?.cursor;
      if (oldest !== undefined && since < oldest - 1) {
        // The gap is real and unrecoverable from memory. Replaying what is left
        // would look like a complete history and quietly omit the middle.
        throw canaError(
          'NotFound',
          `Cannot replay from cursor ${since}: the retained window starts at ${oldest}. `
            + `Only the last ${this.retainedEvents} events are replayable — reload from the `
            + 'database rather than resuming from an incomplete stream.'
        );
      }
    }

    const subscription: Subscription = { listener, active: true };
    this.subscriptions.push(subscription);

    if (since !== undefined) {
      for (const event of this.history.filter((entry) => entry.cursor > since)) {
        try {
          listener(event);
        } catch {
          // Same reasoning as `publish`.
        }
      }
    }

    return () => {
      subscription.active = false;
      const at = this.subscriptions.indexOf(subscription);
      if (at >= 0) this.subscriptions.splice(at, 1);
    };
  }

  async exportAll(): Promise<Record<string, readonly unknown[]>> {
    const database = this.requireOpen();
    const names = Array.from(database.objectStoreNames);
    const dump: Record<string, readonly unknown[]> = {};

    const { result } = await this.transaction('readonly', names, async (scope) => {
      for (const name of names) {
        // eslint-disable-next-line no-await-in-loop
        dump[name] = await scope.table(name).query();
      }
      return dump;
    });

    return result ?? dump;
  }
}

/** Create a client. It is not open until `open()` resolves. */
export function createClient(options: ClientOptions): Client {
  return new Client(options);
}
import Dexie from 'dexie';
import type { CanaSchema } from '../src';
import { createClient } from '../src';

/**
 * Differential harness: Cana against Dexie on identical inputs (JUM-561).
 *
 * Every other suite in this package checks Cana against what I believed
 * IndexedDB does. This one checks it against an independent implementation that
 * has been in production for over a decade — which is the only kind of test that
 * can catch a belief that is wrong in the same way twice.
 *
 * Both run over the browser's own IndexedDB, each under its own database name, so the two
 * see identical storage semantics and differ only in engine.
 *
 * **Dexie is used strictly as a dev-time oracle.** No Dexie code is vendored,
 * copied, or referenced by `@jumentix/cana`; it appears only in this file and
 * only in `devDependencies`, under its own Apache-2.0 terms.
 *
 * ## Where the two are expected to differ
 *
 * Divergence is not automatically a Cana bug. Several differences are documented
 * decisions — `update` not inserting, for instance — and where they occur, the
 * test asserts the difference and says why, rather than being deleted for being
 * inconvenient.
 */

interface Design {
  id: number;
  name: string;
  owner: string;
  size: number;
}

const rows: Design[] = [
  {
    id: 1, name: 'alpha', owner: 'ana', size: 10
  },
  {
    id: 2, name: 'bravo', owner: 'bruno', size: 20
  },
  {
    id: 3, name: 'charlie', owner: 'ana', size: 30
  },
  {
    id: 4, name: 'delta', owner: 'carla', size: 40
  },
  {
    id: 5, name: 'echo', owner: 'ana', size: 50
  },
  {
    id: 6, name: 'foxtrot', owner: 'bruno', size: 60
  }
];

const schema: CanaSchema = {
  version: 1,
  stores: [{
    name: 'designs',
    keyPath: 'id',
    indexes: [
      { name: 'owner', keyPath: 'owner' },
      { name: 'size', keyPath: 'size' }
    ]
  }]
};

/** Both engines, seeded identically, each on its own factory. */
async function bothSeeded() {
  const cana = createClient({ name: 'diff-cana', schema });
  await cana.open();
  await cana.table<Design>('designs').bulkAdd(rows);

  // Dexie reads `indexedDB` from the global, so it is pointed at a fresh factory
  // explicitly rather than sharing one with Cana.
  const dexie = new Dexie('diff-dexie', { indexedDB, IDBKeyRange });
  dexie.version(1).stores({ designs: 'id, owner, size' });
  await dexie.open();
  await dexie.table<Design>('designs').bulkAdd(rows);

  return {
    cana,
    dexie,
    async teardown() {
      await cana.close();
      dexie.close();
    }
  };
}

/** Ids in a stable order, so set equality is what is being compared. */
const ids = (records: readonly Design[]): number[] => records
  .map((row) => row.id)
  .sort((a, b) => a - b);

describe('differential: reads agree with Dexie', () => {
  it('returns the same records for a full scan', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const fromCana = await cana.table<Design>('designs').query();
    const fromDexie = await dexie.table<Design>('designs').toArray();

    expect(ids(fromCana)).to.deep.equal(ids(fromDexie));
    expect(ids(fromCana)).to.deep.equal([1, 2, 3, 4, 5, 6]);
    await teardown();
  });

  it('returns the same records for an equality lookup on an index', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const fromCana = await cana.table<Design>('designs').query({ index: 'owner', equals: 'ana' });
    const fromDexie = await dexie.table<Design>('designs').where('owner').equals('ana').toArray();

    expect(ids(fromCana)).to.deep.equal(ids(fromDexie));
    expect(ids(fromCana)).to.deep.equal([1, 3, 5]);
    await teardown();
  });

  it('agrees on a closed range', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const fromCana = await cana.table<Design>('designs')
      .query({ index: 'size', range: { lower: 20, upper: 50 } });
    const fromDexie = await dexie.table<Design>('designs')
      .where('size').between(20, 50, true, true).toArray();

    expect(ids(fromCana)).to.deep.equal(ids(fromDexie));
    await teardown();
  });

  it('agrees on a half-open range, which is where off-by-one bugs live', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const fromCana = await cana.table<Design>('designs')
      .query({ index: 'size', range: { lower: 20, upper: 50, upperOpen: true } });
    const fromDexie = await dexie.table<Design>('designs')
      .where('size').between(20, 50, true, false).toArray();

    expect(ids(fromCana)).to.deep.equal(ids(fromDexie));
    expect(ids(fromCana)).to.deep.equal([2, 3, 4]);
    await teardown();
  });

  it('agrees on both bounds open', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const fromCana = await cana.table<Design>('designs')
      .query({
        index: 'size',
        range: {
          lower: 20, upper: 50, lowerOpen: true, upperOpen: true
        }
      });
    const fromDexie = await dexie.table<Design>('designs')
      .where('size').between(20, 50, false, false).toArray();

    expect(ids(fromCana)).to.deep.equal(ids(fromDexie));
    expect(ids(fromCana)).to.deep.equal([3, 4]);
    await teardown();
  });

  it('agrees on lower-only and upper-only bounds', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const canaAbove = await cana.table<Design>('designs')
      .query({ index: 'size', range: { lower: 40 } });
    const dexieAbove = await dexie.table<Design>('designs').where('size').aboveOrEqual(40).toArray();

    const canaBelow = await cana.table<Design>('designs')
      .query({ index: 'size', range: { upper: 30 } });
    const dexieBelow = await dexie.table<Design>('designs').where('size').belowOrEqual(30).toArray();

    expect(ids(canaAbove)).to.deep.equal(ids(dexieAbove));
    expect(ids(canaBelow)).to.deep.equal(ids(dexieBelow));
    await teardown();
  });

  it('agrees on ordering by an index, ascending and descending', async () => {
    // Order is asserted directly, not sorted first — the ordering is the claim.
    const { cana, dexie, teardown } = await bothSeeded();

    const canaAsc = await cana.table<Design>('designs').query({ index: 'size' });
    const dexieAsc = await dexie.table<Design>('designs').orderBy('size').toArray();

    const canaDesc = await cana.table<Design>('designs').query({ index: 'size', direction: 'prev' });
    const dexieDesc = await dexie.table<Design>('designs').orderBy('size').reverse().toArray();

    expect(canaAsc.map((row) => row.id)).to.deep.equal(dexieAsc.map((row) => row.id));
    expect(canaDesc.map((row) => row.id)).to.deep.equal(dexieDesc.map((row) => row.id));
    await teardown();
  });

  it('agrees on limit', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const fromCana = await cana.table<Design>('designs').query({ index: 'size', limit: 3 });
    const fromDexie = await dexie.table<Design>('designs').orderBy('size').limit(3).toArray();

    expect(fromCana.map((row) => row.id)).to.deep.equal(fromDexie.map((row) => row.id));
    await teardown();
  });

  it('agrees on offset combined with limit', async () => {
    // Pagination is where a cursor-advance implementation and a slice-after
    // implementation diverge, so it is worth checking against another engine.
    const { cana, dexie, teardown } = await bothSeeded();

    const fromCana = await cana.table<Design>('designs')
      .query({ index: 'size', offset: 2, limit: 2 });
    const fromDexie = await dexie.table<Design>('designs')
      .orderBy('size').offset(2).limit(2)
      .toArray();

    expect(fromCana.map((row) => row.id)).to.deep.equal(fromDexie.map((row) => row.id));
    expect(fromCana.map((row) => row.id)).to.deep.equal([3, 4]);
    await teardown();
  });

  it('agrees on counts, overall and by index', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    expect(await cana.table<Design>('designs').count()).to.equal(await dexie.table<Design>('designs').count());
    expect(await cana.table<Design>('designs').count({ index: 'owner', equals: 'ana' })).to.equal(await dexie.table<Design>('designs').where('owner').equals('ana').count());
    await teardown();
  });

  it('agrees on a lookup that matches nothing', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const fromCana = await cana.table<Design>('designs')
      .query({ index: 'owner', equals: 'nobody' });
    const fromDexie = await dexie.table<Design>('designs').where('owner').equals('nobody').toArray();

    expect(fromCana).to.deep.equal([]);
    expect(fromDexie).to.deep.equal([]);
    await teardown();
  });

  it('agrees on a get for a present and an absent key', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const canaHit = await cana.table<Design>('designs').get(3);
    const dexieHit = await dexie.table<Design>('designs').get(3);

    expect(canaHit?.name).to.equal(dexieHit?.name);
    expect(await cana.table<Design>('designs').get(99)).to.equal(undefined);
    expect(await dexie.table<Design>('designs').get(99)).to.equal(undefined);
    await teardown();
  });
});

describe('differential: writes agree with Dexie', () => {
  it('agrees on the state after a put that replaces', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    await cana.table<Design>('designs').put({
      id: 1, name: 'replaced', owner: 'ana', size: 10
    });
    await dexie.table<Design>('designs').put({
      id: 1, name: 'replaced', owner: 'ana', size: 10
    });

    const canaRow = await cana.table<Design>('designs').get(1);
    const dexieRow = await dexie.table<Design>('designs').get(1);

    expect(canaRow?.name).to.equal(dexieRow?.name);
    expect(await cana.table<Design>('designs').count()).to.equal(await dexie.table<Design>('designs').count());
    await teardown();
  });

  it('agrees on the state after a delete', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    await cana.table<Design>('designs').delete(3);
    await dexie.table<Design>('designs').delete(3);

    const fromCana = await cana.table<Design>('designs').query();
    const fromDexie = await dexie.table<Design>('designs').toArray();

    expect(ids(fromCana)).to.deep.equal(ids(fromDexie));
    await teardown();
  });

  it('agrees that a bulk add of a duplicate key does not silently succeed', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    const canaFailed = await cana.table<Design>('designs')
      .bulkAdd([{
        id: 1, name: 'clash', owner: 'x', size: 1
      }])
      .then(() => false)
      .catch(() => true);
    const dexieFailed = await dexie.table<Design>('designs')
      .bulkAdd([{
        id: 1, name: 'clash', owner: 'x', size: 1
      }])
      .then(() => false)
      .catch(() => true);

    expect(canaFailed).to.equal(true);
    expect(dexieFailed).to.equal(true);
    await teardown();
  });

  it('agrees on the state after a clear', async () => {
    const { cana, dexie, teardown } = await bothSeeded();

    await cana.table<Design>('designs').clear();
    await dexie.table<Design>('designs').clear();

    expect(await cana.table<Design>('designs').count()).to.equal(0);
    expect(await dexie.table<Design>('designs').count()).to.equal(0);
    await teardown();
  });
});

describe('differential: documented divergences', () => {
  it('cana refuses an update on a missing key where Dexie reports zero changes', async () => {
    // A real, intended difference. Dexie's `update` returns 0 for "nothing
    // matched"; Cana throws NotFound.
    //
    // The reason is recorded in the design doc: a caller who ignores the return
    // value — which is the common case — cannot tell a no-op from a success, and
    // an update silently doing nothing is how a stale key becomes lost work.
    // Failing loudly is the decision, and this test pins it rather than letting
    // the divergence look accidental.
    const { cana, dexie, teardown } = await bothSeeded();

    const dexieResult = await dexie.table<Design>('designs').update(99, { name: 'ghost' });
    const canaFailed = await cana.table<Design>('designs')
      .update(99, { name: 'ghost' })
      .then(() => false)
      .catch(() => true);

    expect(dexieResult).to.equal(0);
    expect(canaFailed).to.equal(true);

    // Both agree on the thing that actually matters: nothing was written.
    expect(await cana.table<Design>('designs').count()).to.equal(await dexie.table<Design>('designs').count());
    expect(await cana.table<Design>('designs').get(99)).to.equal(undefined);
    await teardown();
  });

  it('both agree on an update that does match', async () => {
    // The divergence above is confined to the missing-key case; the ordinary
    // path must still agree, or the difference would be a bug rather than a
    // decision.
    const { cana, dexie, teardown } = await bothSeeded();

    await cana.table<Design>('designs').update(2, { name: 'renamed' });
    await dexie.table<Design>('designs').update(2, { name: 'renamed' });

    const canaRow = await cana.table<Design>('designs').get(2);
    const dexieRow = await dexie.table<Design>('designs').get(2);

    expect(canaRow).to.deep.equal(dexieRow);
    await teardown();
  });
});
